        dp[i][i] = beads[i - 1] * beads[i - 2]
        for j in range(i + 1, n + 1):
            dp[i][j] = max(dp[i][j], dp[i][j - 1], dp[i - 1][j], dp[i - 1][j - 1] * beads[j - 1] * beads[i - 1])

