def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    if not coeffs:
        return ""

    result = ""
    for degree, coeff in enumerate(reversed(coeffs), start=1):
        if coeff == 0:
            continue
        sign = "-" if coeff < 0 else "+"
        coeff = abs(coeff)
        if coeff == 1 and degree > 1:
            coefficient_str = "x^" + str(degree-1)
        elif degree == 1:
            coefficient_str = "x"
        elif degree > 0:
            coefficient_str = str(coeff) + "x^" + str(degree-1)
        else:
            coefficient_str = str(coeff)
        result = sign + coefficient_str + result
    return result.strip()

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    remaining_letters = set(original)
    encoded_letters = set(encoded)

    try:
        for i in range(len(encoded)):
            if encoded[i] not in mapping and original[i] in remaining_letters and encoded[i] != original[i]:
                mapping[encoded[i]] = original[i]
                remaining_letters.remove(original[i])
        for original_letter in remaining_letters:
            return "Failed"

        return ''.join(mapping[char] if char in mapping else char for char in message)
    except:
        return "Failed"

