def count_partitions(n: int, k: int, x: int) -> int:
    mod = 10**9 + 7
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(1, min(i, k) + 1):
            dp[i][j] = (dp[i - 1][j] + dp[i - 1][j - 1] * max(0, i - x)) % mod

    return dp[n][k]

def count_sequences(n: int, last: int, memo: dict) -> int:
    if last == 0 or last == 1:
        return 1
    if (n, last) in memo:
        return memo[(n, last)]
    count = 0
    for i in range(1, min(n, last // 2) + 1):
        count += count_sequences(i, n, memo)
    memo[(n, last)] = count
    return count

