    max_steps = 10
    visited = set()

    queue = deque([start_node])

    while queue:
        current_node, current_step = queue.popleft()

        if current_node[0] == B:
            return current_step

        if current_step >= max_steps or current_node in visited:
            continue

        visited.add(current_node)

