        if time <= 0 or idx < 0:
            return 0
        if dp[idx][time] != -1:
            return dp[idx][time]
        dp[idx][time] = max(knapsack_dp(time, val, idx - 1), knapsack_dp(time - herbs[idx][0], val + herbs[idx][1], idx - 1))
