def min_remaining_space(self, V: int, n: int, volumes: List[int]) -> int:
        dp = [[0 for _ in range(V + 1)] for _ in range(n + 1)]

        for i in range(n + 1):
            for j in range(V + 1):
                if i == 0 or j == 0:
                    dp[i][j] = 0
                elif volumes[i - 1] <= j:
                    dp[i][j] = max(volumes[i - 1] + dp[i - 1][j - volumes[i - 1]], dp[i - 1][j])
                else:
                    dp[i][j] = dp[i - 1][j]

        max_occupied = dp[n][V]
        return V - max_occupied

def calculate_arrangements(n, m, a):
