def vigenere_decrypt(key: str, ciphertext: str) -> str:
    if not key.isalpha() or not ciphertext.isalpha():
        raise ValueError("Both key and ciphertext must consist only of alphabetic characters.")

    key_length = len(key)
    plaintext = ""
    for i, char in enumerate(ciphertext):
        shift = ord(key[i % key_length]) - ord('A')
        if char.islower():
            plaintext += chr((ord(char) - ord('a') - shift) % 26 + ord('a'))
        else:
            plaintext += chr((ord(char) - ord('A') - shift) % 26 + ord('A'))
    return plaintext

def mod_inverse(a, b):
    if b == 0:
        return None

    x0, x1 = 1, 0
    y0, y1 = 0, 1

    while b != 0:
        quotient = a // b
        a, b = b, a % b
        x0, x1 = x1, x0 - quotient * x1
        y0, y1 = y1, y0 - quotient * y1

    if a != 1:
        return None

    return x0 % b

def find_most_unhappy_day(schedule) -> int:
    total_hours = sum(hours for hours, _ in schedule)
    threshold = 8
    max_hours = total_hours
    max_day = 0

    for day, hours in enumerate(schedule):
        if hours - threshold > total_hours - threshold:
            total_hours = hours
            max_days = 1
            max_day = day + 1
        elif hours - threshold == total_hours - threshold:
            max_days += 1

    if max_days > 1:
        return min(range(1, 8), key=lambda day: (total_hours - threshold if schedule[day - 1][1] <= threshold else total_hours - threshold - schedule[day - 1][1], day))
    else:
        return max_day if total_hours > threshold else 0

